import {test,before,after} from 'node:test';
import assert from 'node:assert/strict';
import {createServer,request as httpRequest} from 'node:http';
import {setTimeout as wait} from 'node:timers/promises';
import {randomUUID} from 'node:crypto';
import {initializeApp,deleteApp} from 'firebase-admin/app';
import {getAuth} from 'firebase-admin/auth';
import {getFirestore} from 'firebase-admin/firestore';
import {createRequestHandler} from './auth-boundary.mjs';
// TEST-ONLY fixture: identical to mock-api.test.mjs except the main suite handler's explicit rateLimit:{ipBurst:1000} shared-loopback IP budget.
import {createFirebaseVerifier} from './firebase-verifier.mjs';
import {createMockStore} from './mock-store.mjs';
import {createAccountSession} from './account-session.mjs';
import {createMockClient} from './mock-client.mjs';
import {createMockIntent} from './mock-intent.mjs';
const projectId='demo-deltascore-fresh',key=value=>Buffer.from(value,'utf8').toString('base64url');
let app,admin,db,verifier,server,base;
const owner=uid=>db.collection('deltascoreFreshV1').doc(key(uid));
const draft=(id=randomUUID())=>({id,title:'Fictional HTTP mock',provider:'',dmMode:'questions',scores:{VR:{earned:'30',max:'44'},DM:{earned:'25',max:'35'},QR:{earned:'25',max:'36'}},sjt:null,reviews:[],note:'',stage:'selection'});
before(async()=>{
 assert.equal(process.env.FIREBASE_AUTH_EMULATOR_HOST,'127.0.0.1:9099');assert.equal(process.env.FIRESTORE_EMULATOR_HOST,'127.0.0.1:8080');
 app=initializeApp({projectId},'mock-api-fixtures-'+randomUUID());admin=getAuth(app);db=getFirestore(app);verifier=createFirebaseVerifier({mode:'emulator',projectId});
 server=createServer(createRequestHandler({...verifier,mockStore:createMockStore({db}),rateLimit:{ipBurst:1000}}));await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));base='http://127.0.0.1:'+server.address().port;
});
after(async()=>{if(server){server.closeAllConnections();await new Promise((resolve,reject)=>server.close(e=>e?reject(e):resolve()))}if(db)await db.terminate();if(verifier)await verifier.close();if(app)await deleteApp(app)});
async function account(verified=true){const email='fictional-api-'+randomUUID()+'@example.test',password='FictionalEmulatorOnly-42!';const user=await admin.createUser({email,password,emailVerified:verified});const response=await fetch('http://127.0.0.1:9099/identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=fake-api-key',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email,password,returnSecureToken:true})});assert.equal(response.status,200);return {uid:user.uid,token:(await response.json()).idToken}}
async function save(token,input,suffix=''){const response=await fetch(base+'/api/mocks/commit'+suffix,{method:'POST',headers:{'content-type':'application/json',...(token?{authorization:'Bearer '+token}:{}),'x-user-id':'forged-owner'},body:JSON.stringify(input),signal:AbortSignal.timeout(15000)});return {status:response.status,body:await response.json(),cache:response.headers.get('cache-control')}}
test('malformed JSON returns an input error without consuming an allowance',async()=>{
 const a=await account(),response=await fetch(base+'/api/mocks/commit',{method:'POST',headers:{authorization:'Bearer '+a.token,'content-type':'application/json'},body:'{broken',signal:AbortSignal.timeout(15000)});
 assert.equal(response.status,400);assert.deepEqual(await response.json(),{error:'invalid_json'});assert.equal(response.headers.get('cache-control'),'no-store');assert.equal((await owner(a.uid).get()).exists,false);
});
test('save input conflict and allowance failures return explicit non-authentication errors',async()=>{
 const a=await account(),input=draft(),invalid=structuredClone(input);invalid.scores.VR.earned='99';
 let result=await save(a.token,invalid);assert.equal(result.status,400);assert.deepEqual(result.body,{error:'invalid_mock'});assert.equal((await owner(a.uid).get()).exists,false);
 assert.equal((await save(a.token,input)).status,201);const changed=structuredClone(input);changed.scores.VR.earned='31';result=await save(a.token,changed);assert.equal(result.status,409);assert.deepEqual(result.body,{error:'commit_conflict'});
 await save(a.token,draft());await save(a.token,draft());result=await save(a.token,draft());assert.equal(result.status,403);assert.deepEqual(result.body,{error:'initial_allowance_exhausted'});assert.equal((await owner(a.uid).get()).data().used,3);assert.equal((await owner(a.uid).collection('mocks').get()).size,3);
 result=await save(a.token,input);assert.equal(result.status,200);assert.deepEqual(result.body,{created:false,id:input.id,used:3});
 const corrupt=await account();await owner(corrupt.uid).create({ownerUid:corrupt.uid,used:-1});result=await save(corrupt.token,draft());assert.equal(result.status,503);assert.deepEqual(result.body,{error:'storage_unavailable'});assert.equal((await owner(corrupt.uid).get()).data().used,-1);
});
test('save endpoint accepts only supported JSON representations',async()=>{
 const a=await account();for(const headers of [{'content-type':'text/plain'},{'content-type':'application/json','content-encoding':'gzip'}]){
  const response=await fetch(base+'/api/mocks/commit',{method:'POST',headers:{authorization:'Bearer '+a.token,...headers},body:JSON.stringify(draft()),signal:AbortSignal.timeout(15000)});assert.equal(response.status,415);assert.deepEqual(await response.json(),{error:'unsupported_media_type'});
 }
 assert.equal((await owner(a.uid).get()).exists,false);
});
test('oversized chunked and fixed-length bodies are rejected without allocating an allowance',async()=>{
 const a=await account();
 async function* oversized(){for(let i=0;i<10;i++)yield ' '.repeat(1024*1024);yield '{}'}
 for(const options of [{body:oversized(),duplex:'half'},{body:' '.repeat(9*1024*1024+1)+'{}'}]){
  const response=await fetch(base+'/api/mocks/commit',{method:'POST',headers:{authorization:'Bearer '+a.token,'content-type':'application/json'},...options,signal:AbortSignal.timeout(15000)});
  assert.equal(response.status,413);assert.deepEqual(await response.json(),{error:'payload_too_large'});assert.equal(response.headers.get('cache-control'),'no-store');
 }
 assert.equal((await owner(a.uid).get()).exists,false);assert.equal((await owner(a.uid).collection('receipts').get()).size,0);
});
test('anonymous invalid unverified disabled and revoked save requests never allocate an allowance',async()=>{
 const verified=await account(),unverified=await account(false),disabled=await account(),revoked=await account();await admin.updateUser(disabled.uid,{disabled:true});await wait(1100);await admin.revokeRefreshTokens(revoked.uid);
 for(const [token,status,error] of [[null,401,'authentication_required'],['not-a-token',401,'invalid_authentication'],[unverified.token,403,'email_verification_required'],[disabled.token,401,'invalid_authentication'],[revoked.token,401,'invalid_authentication']]){
  const result=await save(token,draft());assert.equal(result.status,status);assert.deepEqual(result.body,{error});assert.equal(result.cache,'no-store');
 }
 for(const user of [verified,unverified,disabled,revoked])assert.equal((await owner(user.uid).get()).exists,false);
});
test('two signed-in accounts using one draft ID retain independent records reviews and quotas',async()=>{
 const a=await account(),b=await account(),input=draft();input.reviews=[{section:'VR',number:'1',format:'guided',thinking:'Fictional A only',instead:'',free:'',type:'',reasons:[],other:'',reviewed:false,confirmed:false}];
 assert.equal((await save(a.token,{...input,uid:b.uid})).status,201);const second=structuredClone(input);second.title='Fictional B only';second.reviews[0].thinking='Fictional B only';assert.equal((await save(b.token,{...second,uid:a.uid})).status,201);
 for(const [user,title,text] of [[a,input.title,'Fictional A only'],[b,second.title,'Fictional B only']]){
  const ref=owner(user.uid).collection('mocks').doc(key(input.id)),record=(await ref.get()).data(),review=(await ref.collection('reviews').doc(key('VR:1')).get()).data();assert.equal(record.title,title);assert.equal(record.ownerUid,user.uid);assert.equal(review.review.thinking,text);assert.equal(review.ownerUid,user.uid);assert.equal((await owner(user.uid).get()).data().used,1);
 }
});
test('authenticated students cannot directly read or alter the server-owned Firestore namespace',async()=>{
 const a=await account(),b=await account();await save(a.token,draft());await save(b.token,draft());
 for(const target of [a,b]){
  const url='http://127.0.0.1:8080/v1/projects/'+projectId+'/databases/(default)/documents/'+owner(target.uid).path;
  const read=await fetch(url,{headers:{authorization:'Bearer '+a.token},signal:AbortSignal.timeout(10000)});assert.equal(read.status,403);await read.arrayBuffer();
  const write=await fetch(url,{method:'PATCH',headers:{authorization:'Bearer '+a.token,'content-type':'application/json'},body:JSON.stringify({fields:{used:{integerValue:'-99'}}}),signal:AbortSignal.timeout(10000)});assert.equal(write.status,403);await write.arrayBuffer();assert.equal((await owner(target.uid).get()).data().used,1);
 }
});
test('save method restrictions and duplicate authorization fail before any durable change',async()=>{
 const a=await account();for(const method of ['GET','PUT','DELETE','OPTIONS']){const response=await fetch(base+'/api/mocks/commit',{method,headers:{authorization:'Bearer '+a.token},signal:AbortSignal.timeout(10000)});assert.equal(response.status,405);assert.equal(response.headers.get('allow'),'POST');assert.deepEqual(await response.json(),{error:'method_not_allowed'})}
 const result=await new Promise((resolve,reject)=>{const request=httpRequest(base+'/api/mocks/commit',{method:'POST',headers:['Host',new URL(base).host,'Authorization','Bearer '+a.token,'Authorization','Bearer '+a.token,'Content-Type','application/json']},response=>{let body='';response.setEncoding('utf8');response.on('data',chunk=>body+=chunk);response.on('end',()=>resolve({status:response.statusCode,body:JSON.parse(body)}))});request.setTimeout(10000,()=>request.destroy(new Error('Fixture request timed out')));request.on('error',reject);request.end(JSON.stringify(draft()))});assert.equal(result.status,401);assert.deepEqual(result.body,{error:'authentication_required'});assert.equal((await owner(a.uid).get()).exists,false);
});
test('private saved-record retrieval restores full question order and content without consuming allowance',async()=>{
 const a=await account(),input=draft();input.reviews=[{section:'VR',number:'2',format:'guided',thinking:'Fictional earlier reasoning',instead:'Try a different method',free:'R'.repeat(60000),type:'',reasons:[],other:'',reviewed:false,confirmed:false},{section:'QR',number:'1',format:'free',thinking:'',instead:'',free:'Fictional second question',type:'',reasons:[],other:'',reviewed:true,confirmed:true}];assert.equal((await save(a.token,input)).status,201);
 const response=await fetch(base+'/api/mocks/item?id='+encodeURIComponent(input.id),{headers:{authorization:'Bearer '+a.token},signal:AbortSignal.timeout(15000)});assert.equal(response.status,200);assert.equal(response.headers.get('cache-control'),'no-store');const body=await response.json();const {loggedAt,...record}=body.mock,{stage,...expected}=input;
 assert.deepEqual(record,expected);assert.equal(loggedAt,(await owner(a.uid).collection('mocks').doc(key(input.id)).get()).data().loggedAt);assert.equal((await owner(a.uid).get()).data().used,1);assert.equal((await owner(a.uid).collection('receipts').get()).size,1);
});
