test('corrupt owned-record metadata never returns foreign-owner or incomplete review content',async()=>{
 const a=await account(),input=draft();input.reviews=[{section:'VR',number:'1',format:'guided',thinking:'Fictional private review',instead:'',free:'',type:'',reasons:[],other:'',reviewed:false,confirmed:false}];await save(a.token,input);const ref=owner(a.uid).collection('mocks').doc(key(input.id)),question=ref.collection('reviews').doc(key('VR:1'));
 async function unavailable(){const response=await fetch(base+'/api/mocks/item?id='+encodeURIComponent(input.id),{headers:{authorization:'Bearer '+a.token},signal:AbortSignal.timeout(15000)});assert.equal(response.status,503);assert.deepEqual(await response.json(),{error:'storage_unavailable'});assert.equal(response.headers.get('cache-control'),'no-store')}
 await ref.update({ownerUid:'fictional-other-owner'});await unavailable();await ref.update({ownerUid:a.uid});
 await question.update({ownerUid:'fictional-other-owner'});await unavailable();await question.update({ownerUid:a.uid});
 await question.set({ownerUid:a.uid,position:0});await unavailable();
 await question.set({ownerUid:a.uid,position:0,review:{}});await unavailable();
 await question.delete();await unavailable();assert.equal((await owner(a.uid).get()).data().used,1);assert.equal((await owner(a.uid).collection('receipts').get()).size,1);
});
