 assert.deepEqual((await ref.get()).data(),before);assert.deepEqual((await readSaved(a,input.id)).body,current.body);assert.equal((await owner(a.uid).get()).data().used,1);assert.equal((await owner(a.uid).collection('receipts').get()).size,1);
