test('review HTTP credential input and method failures leave saved content unchanged',async()=>{
 const a=await account(),unverified=await account(false),disabled=await account(),revoked=await account(),input=draft();input.reviews=[question('VR',1,'Fictional preserved content')];await save(a.token,input);const ref=owner(a.uid).collection('mocks').doc(key(input.id)),before=(await ref.get()).data(),url=base+'/api/mocks/reviews?id='+encodeURIComponent(input.id),payload=JSON.stringify({reviews:[]}),headers={authorization:'Bearer '+a.token,'content-type':'application/json','if-match':'"review-0"'};
 await admin.updateUser(disabled.uid,{disabled:true});await wait(1100);await admin.revokeRefreshTokens(revoked.uid);
 for(const [token,status,error] of [[null,401,'authentication_required'],['not-a-token',401,'invalid_authentication'],[unverified.token,403,'email_verification_required'],[disabled.token,401,'invalid_authentication'],[revoked.token,401,'invalid_authentication']]){const response=await fetch(url,{method:'PATCH',headers:{'content-type':'application/json','if-match':'"review-0"',...(token?{authorization:'Bearer '+token}:{})},body:payload,signal:AbortSignal.timeout(15000)});assert.equal(response.status,status);assert.deepEqual(await response.json(),{error});assert.equal(response.headers.get('cache-control'),'no-store')}
 for(const method of ['GET','POST','PUT','DELETE','OPTIONS']){const response=await fetch(url,{method,headers,signal:AbortSignal.timeout(15000)});assert.equal(response.status,405);assert.equal(response.headers.get('allow'),'PATCH');assert.deepEqual(await response.json(),{error:'method_not_allowed'})}
 for(const [extra,body,status,error] of [[{},'{broken',400,'invalid_json'],[{'content-type':'text/plain'},payload,415,'unsupported_media_type'],[{'content-encoding':'gzip'},payload,415,'unsupported_media_type'],[{},' '.repeat(9*1024*1024+1)+'{}',413,'payload_too_large']]){const response=await fetch(url,{method:'PATCH',headers:{...headers,...extra},body,signal:AbortSignal.timeout(15000)});assert.equal(response.status,status);assert.deepEqual(await response.json(),{error});assert.equal(response.headers.get('cache-control'),'no-store')}
 for(const id of ['', 'x'.repeat(129)]){const response=await fetch(base+'/api/mocks/reviews?id='+encodeURIComponent(id),{method:'PATCH',headers,body:payload,signal:AbortSignal.timeout(15000)});assert.equal(response.status,400);assert.deepEqual(await response.json(),{error:'invalid_mock_id'})}
 assert.deepEqual((await ref.get()).data(),before);assert.deepEqual((await readSaved(a,input.id)).body.mock.reviews,input.reviews);assert.equal((await owner(a.uid).get()).data().used,1);assert.equal((await owner(a.uid).collection('receipts').get()).size,1);for(const user of [unverified,disabled,revoked])assert.equal((await owner(user.uid).get()).exists,false);
});
