test('deletion requires the current review revision and serializes against review edits',async()=>{
 const a=await account(),input=draft();await save(a.token,input);const first={reviews:[question('VR',1,'Fictional current review')]};assert.equal((await editSaved(a,input.id,'"review-0"',first)).status,200);
 for(const [etag,status,error] of [[null,428,'review_version_required'],['*',400,'invalid_review_version'],['"review--1"',400,'invalid_review_version'],['"review-9007199254740992"',400,'invalid_review_version'],['"review-0"',412,'review_conflict']]){const result=await removeSaved(a,input.id,etag);assert.equal(result.status,status);assert.deepEqual(result.body,{error});assert.equal(result.cache,'no-store')}
 const current=await readSaved(a,input.id);assert.deepEqual(current.body.mock.reviews,first.reviews);const replacement={reviews:[question('QR',2,'Fictional racing review')]},[removed,edited]=await Promise.all([removeSaved(a,input.id,current.etag),editSaved(a,input.id,current.etag,replacement)]),ref=owner(a.uid).collection('mocks').doc(key(input.id));
 if(removed.status===200){assert.equal(edited.status,404);assert.equal((await ref.get()).exists,false);assert.equal((await ref.collection('reviews').get()).size,0)}else{assert.equal(removed.status,412);assert.equal(edited.status,200);const latest=await readSaved(a,input.id);assert.deepEqual(latest.body.mock.reviews,replacement.reviews);assert.equal(latest.etag,'"review-2"');assert.equal((await removeSaved(a,input.id,latest.etag)).status,200);assert.equal((await ref.collection('reviews').get()).size,0)}
 assert.equal((await owner(a.uid).get()).data().used,1);assert.equal((await owner(a.uid).collection('receipts').get()).size,1);
});
