test('connected catalogue client pages owned summaries and reopens full records through guarded intents over actual HTTP',async()=>{
 const a=await account(),b=await account(),id='历史/二 connected?literal&space=one two';
 const inputA=draft(id);inputA.title='Fictional connected A record';inputA.provider='Fictional provider';inputA.sjt={earned:'40',max:'69'};inputA.reviews=[question('SJT',1,'Fictional connected A private review')];inputA.note='Fictional connected A private note';
 const secondA=draft('same ID');secondA.title='Fictional connected A second record';const thirdA=draft('mock/one ?=a');thirdA.title='Fictional connected A third record';const inputB=draft(id);inputB.title='Fictional connected B record';
 assert.equal((await save(a.token,inputA)).status,201);assert.equal((await save(a.token,secondA)).status,201);assert.equal((await save(a.token,thirdA)).status,201);assert.equal((await save(b.token,inputB)).status,201);
 assert.equal((await editSaved(a,secondA.id,'\"review-0\"',{reviews:[question('VR',1,'Fictional connected revision')]})).status,200);
 let requests=0,view={},session=createAccountSession({verifySession:async token=>{const response=await fetch(base+'/api/session',{headers:{authorization:'Bearer '+token},signal:AbortSignal.timeout(15000)});assert.equal(response.status,200);return response.json()}}),user=account=>({uid:account.uid,getIdToken:async()=>account.token}),api=createMockClient({session,fetcher:async(path,options)=>{requests++;return fetch(base+path,options)}}),scoped=()=>{const captured=view;return createMockIntent({session,client:api,isCurrent:()=>view===captured})};
 await session.setAccount(user(a));const aScope=scoped();const expected=[inputA.id,secondA.id,thirdA.id].slice().sort((x,y)=>key(x)<key(y)?-1:1);const seen=[],rows=[];let after=null;
 do{const page=await aScope.listMocks({limit:1,after});page.apply(data=>{for(const row of data.items)rows.push(row)});const row=page.data.items[0];assert.deepEqual(Object.keys(row).sort(),['etag','summary']);seen.push(row.summary.id);after=page.data.nextCursor;if(after!==null)assert.equal(after,key(row.summary.id))}while(after!==null);
 assert.deepEqual(seen,expected);assert.equal(new Set(seen).size,seen.length);
 const inputs=[inputA,secondA,thirdA];
 for(const row of rows){const input=inputs.find(candidate=>candidate.id===row.summary.id),expectedReviews=input===secondA?[question('VR',1,'Fictional connected revision')]:input.reviews,detail=await aScope.getMock(row.summary.id);assert.equal(detail.data.etag,row.etag);assert.deepEqual(detail.data.mock.reviews,expectedReviews);assert.equal(detail.data.mock.note,input.note);assert.equal(detail.data.mock.title,input.title);assert.deepEqual(detail.data.mock.scores,input.scores);assert.deepEqual(detail.data.mock.sjt,input.sjt);let opened;detail.apply(data=>opened=data.mock);assert.equal(opened.title,input.title);assert.deepEqual(opened.reviews,expectedReviews)}
 await session.setAccount(user(b));const bScope=scoped(),bPage=await bScope.listMocks();assert.deepEqual(bPage.data.items.map(row=>row.summary.id),[id]);assert.deepEqual(bPage.data.items[0].summary.title,'Fictional connected B record');const bDetail=await bScope.getMock(id);assert.deepEqual(bDetail.data.mock.reviews,[]);assert.equal(bDetail.data.mock.title,'Fictional connected B record');assert.equal(bDetail.data.etag,'"review-0"');
 const count=requests;for(const stale of ['stale-a-scope']){await assert.rejects(aScope.listMocks(),error=>error.code==='stale_account');await assert.rejects(aScope.listMocks({limit:2}),error=>error.code==='stale_account')}assert.equal(requests,count);
 const viewScope=scoped(),listReceipt=await viewScope.listMocks({limit:1});assert.equal(listReceipt.data.items.length,1);const beforeDeparture=requests;view={};assert.throws(()=>listReceipt.apply(()=>{}),error=>error.code==='stale_intent');await assert.rejects(viewScope.listMocks({limit:2}),error=>error.code==='stale_intent');await assert.rejects(viewScope.listMocks(),error=>error.code==='stale_intent');assert.equal(requests,beforeDeparture);
 await session.setAccount(user(a));let release,arrive,hold=true;const gate=new Promise(yes=>release=yes),arrived=new Promise(yes=>arrive=yes);const heldApi=createMockClient({session,fetcher:async(path,options)=>{const response=await fetch(base+path,options);if(hold){hold=false;arrive(true);await gate}return response}}),heldView=view,heldScopeApi=createMockIntent({session,client:heldApi,isCurrent:()=>view===heldView});const pending=heldScopeApi.listMocks(),discarded=assert.rejects(pending.then(reply=>reply.apply(()=>{})),error=>error.code==='stale_account');discarded.catch(()=>{});await arrived;await session.setAccount(user(b));const stable=session.getState();release();await discarded;assert.equal(session.getState(),stable);assert.equal(stable.uid,b.uid);
 const revoked=await account();assert.equal((await save(revoked.token,draft())).status,201);assert.equal((await save(revoked.token,draft())).status,201);await session.setAccount(user(revoked));const revokedScope=scoped();const firstPage=await revokedScope.listMocks({limit:1});assert.equal(firstPage.data.items.length,1);assert.ok(firstPage.data.nextCursor!==null);await wait(1100);await admin.revokeRefreshTokens(revoked.uid);await assert.rejects(revokedScope.listMocks({limit:1,after:firstPage.data.nextCursor}),error=>error.code==='invalid_authentication'&&error.status===401);
 await session.setAccount(user(a));const currentScope=scoped();await assert.rejects(currentScope.listMocks({limit:0}),error=>error.code==='invalid_list_request');await assert.rejects(currentScope.listMocks({after:'Zg='}),error=>error.code==='invalid_list_request');
 const full=await currentScope.listMocks({limit:20});assert.deepEqual(full.data.items.map(row=>row.summary.id),expected);assert.equal(full.data.nextCursor,null);
 assert.equal((await owner(a.uid).get()).data().used,3);assert.equal((await owner(a.uid).collection('receipts').get()).size,3);assert.equal((await owner(b.uid).get()).data().used,1);assert.equal((await owner(b.uid).get()).exists,true);
 const text=JSON.stringify(full.data);assert.equal(text.includes(a.uid),false);assert.equal(text.includes('Fictional connected A private review'),false);assert.equal(text.includes('Fictional connected A private note'),false);assert.equal(text.includes('reviewRevision'),false);assert.equal(text.includes('ownerUid'),false);
});
test('connected catalogue round-trips leading-BOM and NUL literal identities through real HTTP save list and detail',async()=>{
 const a=await account(),bomId='\uFEFFbom/record one',nulId='nul\u0000record two',plainId='plain record three';
 const bomInput=draft(bomId),nulInput=draft(nulId),plainInput=draft(plainId);bomInput.title='Fictional BOM record';nulInput.title='Fictional NUL record';plainInput.title='Fictional plain record';
 assert.equal((await save(a.token,bomInput)).status,201);assert.equal((await save(a.token,nulInput)).status,201);assert.equal((await save(a.token,plainInput)).status,201);
 const expected=[bomId,nulId,plainId].slice().sort((x,y)=>key(x)<key(y)?-1:1);assert.deepEqual(expected,[bomId,nulId,plainId]);
 const first=await listSaved(a,'?limit=1');assert.equal(first.status,200);assert.equal(first.body.items[0].summary.id,bomId);assert.equal(first.body.nextCursor,key(bomId));
 const second=await listSaved(a,'?limit=1&after='+encodeURIComponent(first.body.nextCursor));assert.equal(second.status,200);assert.equal(second.body.items[0].summary.id,nulId);assert.equal(second.body.nextCursor,key(nulId));
 const third=await listSaved(a,'?limit=1&after='+encodeURIComponent(second.body.nextCursor));assert.equal(third.status,200);assert.equal(third.body.items[0].summary.id,plainId);assert.equal(third.body.nextCursor,null);
 const session=createAccountSession({verifySession:async token=>{const response=await fetch(base+'/api/session',{headers:{authorization:'Bearer '+token},signal:AbortSignal.timeout(15000)});assert.equal(response.status,200);return response.json()}}),user=account=>({uid:account.uid,getIdToken:async()=>account.token}),api=createMockClient({session,fetcher:(path,options)=>fetch(base+path,options)});
 await session.setAccount(user(a));
 const seen=[],rows=[];let after=null;
 do{const page=await api.listMocks({limit:1,after});page.apply(data=>{for(const row of data.items)rows.push(row)});const row=page.data.items[0];seen.push(row.summary.id);after=page.data.nextCursor;if(after!==null)assert.equal(after,key(row.summary.id))}while(after!==null);
 assert.deepEqual(seen,expected);assert.equal(rows[0].summary.id,bomId);assert.equal(rows[1].summary.id,nulId);assert.equal(rows[2].summary.id,plainId);
 const continued=await api.listMocks({limit:1,after:key(nulId)});assert.deepEqual(continued.data.items.map(row=>row.summary.id),[plainId]);assert.equal(continued.data.nextCursor,null);
 for(const [row,input] of [[rows[0],bomInput],[rows[1],nulInput]]){const detail=await api.getMock(row.summary.id);assert.equal(detail.data.mock.id,input.id);assert.equal(detail.data.etag,row.etag);assert.equal(detail.data.mock.title,input.title);let opened;detail.apply(data=>opened=data.mock);assert.equal(opened.id,input.id)}
 const full=await api.listMocks({limit:20});assert.deepEqual(full.data.items.map(row=>row.summary.id),expected);assert.equal(full.data.nextCursor,null);
 assert.equal((await owner(a.uid).get()).data().used,3);assert.equal((await owner(a.uid).collection('receipts').get()).size,3);
});
test('authenticated final-save API uses verified account rather than submitted owner',async()=>{
 const a=await account(),b=await account(),input={...draft(),uid:b.uid,ownerUid:b.uid,used:-99};const result=await save(a.token,input,'?uid='+b.uid);
 assert.equal(result.status,201);assert.deepEqual(result.body,{created:true,id:input.id,used:1});assert.equal(result.cache,'no-store');
 const saved=(await owner(a.uid).collection('mocks').doc(key(input.id)).get()).data();assert.equal(saved.ownerUid,a.uid);assert.deepEqual(saved.scores,input.scores);assert.equal((await owner(a.uid).get()).data().used,1);assert.equal((await owner(b.uid).get()).exists,false);
});
